"""Owner pattern-evaluation successor (candidate 04; review-03 RF-1 and RF-2).

SELECTED FINAL OWNER. The declared JSON Schema 2020-12 dialect wins: every `pattern` keyword evaluated by the pinned
foundation/canonical.py ExactValidator (the validator behind native_evidence_model.v2 validate_native / native_identity,
provider_startup_model.v1 and provider_wire_model.v1 validation, and every other canonical.validate caller) is an
ECMA-262 RegExp with flags `u`, not a Python `re` expression. The owner path pattern whose negative lookahead
`(?!.*(^|/)\\.\\.?(/|$))` stops at the first line terminator is corrected to scan the COMPLETE string,
`(?![\\s\\S]*(^|/)\\.\\.?(/|$))`, at EVERY occurrence in the pinned owner schema documents. Model regular expressions
that compile or mirror owner schema patterns follow the same law.

Consequences: `a/..<LF>`, `..<LF>` and `a/.<LF>` are legitimate names (a segment `..<LF>` is not `..`) and are admitted
by the owner; `x<LF>/../y` and `a<U+2028>/../b` contain a real `..` segment and are refused. No spelling is normalized,
coerced or truncated. The alternative of refusing every string on which the two dialects disagree was not taken: it
would invent a restriction on POSIX file names instead of fixing the declared-schema semantics.

install() applies the successor in memory to freshly loaded instances of the PINNED models (never to source files):
it extends every loaded canonical.ExactValidator with the ECMA pattern keyword, applies schemaPatternRows to every
loaded owner schema document (verifying each `from` value), rebuilds module registries over those documents, and
recompiles modelRegexRows through the differential-checked translation tools/wirecodec.ecma_to_python.
"""
import ast
import copy
import hashlib
import importlib.util
import json
import re
from pathlib import Path

from jsonschema import validators
from jsonschema.exceptions import ValidationError
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

import wirecodec as W

MARK = "OPENSIP_OWNER_PATTERN_SUCCESSOR"
DEFECT_TOKEN = "(?!.*("
CORRECT_TOKEN = "(?![\\s\\S]*("
FLAGS = "u"
EVALUATED_DOC_KEYS = ["evidence", "startup", "handshake", "occupancy", "factBatch3"]
MODEL_FILES = {"nativeModel": "native_evidence_model.v2.py", "startupModel": "provider_startup_model.v1.py", "wireModel": "provider_wire_model.v1.py"}
WRAPPED_SELECTORS = ["dependency_source_set_admit", "prepared_output_set_admit", "generated_include_lookup", "file_manifest_identity", "_source_kind", "parse_cargo_lock"]


def _esc(k):
    return k.replace("~", "~0").replace("/", "~1")


def corrected(pattern):
    return pattern.replace(DEFECT_TOKEN, CORRECT_TOKEN)


def pattern_rows(doc):
    """Every `pattern` in the whole document containing the terminator-bounded lookahead, with its correction."""
    rows = []

    def walk(o, p):
        if isinstance(o, dict):
            for k, v in o.items():
                q = p + "/" + _esc(k)
                if k == "pattern" and isinstance(v, str) and DEFECT_TOKEN in v:
                    rows.append({"document": doc["$id"], "pointer": q, "from": v, "to": corrected(v)})
                walk(v, q)
        elif isinstance(o, list):
            for i, v in enumerate(o):
                walk(v, p + "/" + str(i))
    walk(doc, "#")
    return rows


def node_at(doc, pointer):
    node = doc
    for part in [x for x in pointer.lstrip("#").split("/") if x]:
        part = part.replace("~1", "/").replace("~0", "~")
        node = node[int(part)] if isinstance(node, list) else node[part]
    return node


def apply_rows(doc, rows):
    for r in rows:
        if r["document"] != doc.get("$id"):
            continue
        parent_ptr, last = r["pointer"].rsplit("/", 1)
        parent = node_at(doc, parent_ptr)
        if parent.get(last) != r["from"]:
            raise ValueError("owner pattern successor row does not match the pinned value: " + r["pointer"])
        parent[last] = r["to"]


def effective_docs(docs, rows):
    out = {sid: copy.deepcopy(d) for sid, d in docs.items()}
    for d in out.values():
        apply_rows(d, rows)
    return out


# ---------------------------------------------------------------- source digests (review-03 A-9)
def _defs(text):
    tree = ast.parse(text)
    defs = {}
    for n in tree.body:
        if isinstance(n, (ast.FunctionDef, ast.ClassDef)):
            defs[n.name] = n
        elif isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name):
            defs[n.targets[0].id] = n
    return defs


def source_closure(text, roots):
    """sha256 of the exact source segment of every module-level definition transitively named by the roots."""
    defs = _defs(text)
    seen, stack = [], list(roots)
    while stack:
        name = stack.pop()
        if name in seen or name not in defs:
            continue
        seen.append(name)
        for x in ast.walk(defs[name]):
            if isinstance(x, ast.Name) and x.id in defs and x.id not in seen:
                stack.append(x.id)
    return {name: hashlib.sha256(ast.get_source_segment(text, defs[name]).encode("utf-8")).hexdigest() for name in sorted(seen)}


def validate_callers(text):
    """Module-level functions of a model that call canonical validation (C.validate or C.ExactValidator)."""
    out = []
    for name, node in _defs(text).items():
        if not isinstance(node, ast.FunctionDef):
            continue
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "C" and x.attr in ("validate", "ExactValidator"):
                out.append(name)
                break
    return sorted(out)


# ---------------------------------------------------------------- model regex inventory
def _normalize_python_regex(src):
    return src.replace("\\x00", "\\u0000")[:-1] + "(?![\\s\\S])" if src.endswith("$") else src.replace("\\x00", "\\u0000")


def regex_inventory(model_text, evidence_doc):
    """Every `re.<call>(...)` in the pinned native model, classified. schema-derived: compiles an owner schema pattern;
    mirrors-owner-schema-pattern: a Python literal whose ECMA normalization equals an owner schema pattern; model-local:
    an authored Python regex that is not a schema pattern (outside the declared-schema dialect law; unchanged)."""
    tree = ast.parse(model_text)
    names = {}
    for n in tree.body:
        if isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name):
            names[id(n.value)] = n.targets[0].id
    schema_patterns = {}

    def walk(o, p):
        if isinstance(o, dict):
            for k, v in o.items():
                if k == "pattern" and isinstance(v, str):
                    schema_patterns.setdefault(v, p + "/pattern")
                walk(v, p + "/" + _esc(k))
        elif isinstance(o, list):
            for i, v in enumerate(o):
                walk(v, p + "/" + str(i))
    walk(evidence_doc, "#")
    rows = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name) and node.func.value.id == "re":
            arg = ast.get_source_segment(model_text, node.args[0]) if node.args else ""
            row = {"line": node.lineno, "call": "re." + node.func.attr, "name": names.get(id(node)), "argument": arg}
            m = re.fullmatch(r'SCHEMAS\["\$defs"\]\["([A-Za-z0-9]+)"\]\["pattern"\]', arg)
            literal = None
            if arg[:2] in ('r"', "r'"):
                literal = ast.literal_eval(arg)
            if m:
                row.update(kind="schema-derived", schemaPointer="#/$defs/" + m.group(1) + "/pattern")
            elif literal is not None and _normalize_python_regex(literal) in schema_patterns:
                row.update(kind="mirrors-owner-schema-pattern", schemaPointer=schema_patterns[_normalize_python_regex(literal)])
            else:
                row.update(kind="model-local")
            rows.append(row)
    return sorted(rows, key=lambda r: r["line"])


def regex_rows(inventory, effective_evidence):
    return [{"module": MODEL_FILES["nativeModel"], "name": r["name"], "kind": r["kind"], "schemaPointer": r["schemaPointer"],
             "ecmaPattern": node_at(effective_evidence, r["schemaPointer"].rsplit("/", 1)[0])["pattern"]}
            for r in inventory if r["kind"] != "model-local"]


def successor_document(raw, pin_rows):
    docs = {key: json.loads(raw(key)) for key in EVALUATED_DOC_KEYS}
    rows = [r for key in EVALUATED_DOC_KEYS for r in pattern_rows(docs[key])]
    effective_evidence = effective_docs({docs["evidence"]["$id"]: docs["evidence"]}, rows)[docs["evidence"]["$id"]]
    model_text = raw("nativeModel").decode("utf-8")
    inventory = regex_inventory(model_text, docs["evidence"])
    texts = {k: raw(k).decode("utf-8") for k in ("nativeModel", "startupModel", "wireModel")}
    pins = {r["key"]: r for r in pin_rows}
    return {
        "artifact": "opensip.native-evidence.owner-pattern-evaluation.successor", "version": "1",
        "standing": "AUTHOR candidate 04 scoped successor to the owner schema pattern evaluation of foundation/canonical.py ExactValidator and to every occurrence of the terminator-bounded path lookahead in the pinned owner schema documents. Parent bytes unchanged; applied in memory by tools/owner_successor.py; not approval.",
        "parents": [pins[k] for k in EVALUATED_DOC_KEYS + ["canonical", "nativeModel", "startupModel", "wireModel"]],
        "selectedOwner": {
            "law": "Every owner schema `pattern` is an ECMA-262 RegExp evaluated with flags u (JSON Schema 2020-12), by every loaded canonical ExactValidator instance; model regexes that compile or mirror owner schema patterns evaluate the same ECMA pattern.",
            "chosenOver": ["Python re evaluation by the pinned canonical ExactValidator", "refusing every string on which ECMA and Python re disagree (a new restriction on POSIX file names)"],
            "reason": "the schema documents declare JSON Schema 2020-12, whose pattern dialect is ECMA-262; the declared semantics are corrected rather than a file-name restriction invented"},
        "evaluator": {"keyword": "pattern", "engine": "ECMA-262 RegExp", "flags": FLAGS,
                      "validator": "foundation/canonical.py ExactValidator, extended in every loaded instance (native model C and IM.C, startup model C, wire model C)",
                      "translation": "tools/wirecodec.py ecma_to_python, differential-checked against the pinned ECMA-262 engine over every owner pattern (check ecma-owner-differential)",
                      "reference": "tools/owner_successor.py install"},
        "patternCorrection": {"defectToken": DEFECT_TOKEN, "correctToken": CORRECT_TOKEN,
                              "why": "`.` excludes the four line terminators, so the lookahead never saw a `..` segment after a terminator; `[\\s\\S]` scans the complete string, while `(^|/)` and `(/|$)` keep exact segment boundaries (no m flag), so `..<LF>` stays a legitimate segment"},
        "schemaPatternRows": rows,
        "modelRegexInventory": inventory,
        "modelRegexRows": regex_rows(inventory, effective_evidence),
        "selectorSources": {
            "canonical": source_closure(raw("canonical").decode("utf-8"), ["validate", "ExactValidator"]),
            "nativeModel": source_closure(model_text, WRAPPED_SELECTORS + validate_callers(model_text)),
            "startupModel": source_closure(texts["startupModel"], validate_callers(texts["startupModel"])),
            "wireModel": source_closure(texts["wireModel"], validate_callers(texts["wireModel"])),
        },
        "unchanged": ["every parent byte", "every pattern without the terminator-bounded lookahead", "model-local Python regexes (modelRegexInventory kind model-local)", "all non-pattern keywords and the canonical const/enum/order/integer semantics"],
    }


# ---------------------------------------------------------------- reference installation
def ecma_validator_class(base, flags):
    def pattern(validator, patrn, instance, schema):
        if validator.is_type(instance, "string") and not W.ecma_test(patrn, flags, instance):
            yield ValidationError("%r does not match ECMA-262 /%s/%s" % (instance, patrn, flags))
    return validators.extend(base, {"pattern": pattern})


def _canonical_modules(mod):
    out, frontier = [], [mod]
    for m in frontier:
        for v in list(vars(m).values()):
            if type(v).__name__ == "module" and hasattr(v, "__file__") and v not in frontier and "design-corrections" in str(getattr(v, "__file__", "")):
                frontier.append(v)
    for m in frontier:
        if hasattr(m, "ExactValidator") and hasattr(m, "validate") and m not in out:
            out.append(m)
    return out


def install(mod, succ):
    flags = succ["evaluator"]["flags"]
    for C in _canonical_modules(mod):
        if not getattr(C, MARK, False):
            C.ExactValidator = ecma_validator_class(C.ExactValidator, flags)
            setattr(C, MARK, True)
    docs = [v for v in vars(mod).values() if isinstance(v, dict) and isinstance(v.get("$id"), str) and "$defs" in v]
    for d in docs:
        apply_rows(d, succ["schemaPatternRows"])
    if isinstance(getattr(mod, "REGISTRY", None), Registry):
        mod.REGISTRY = Registry().with_resources([(d["$id"], Resource(contents=d, specification=DRAFT202012)) for d in docs])
    if Path(getattr(mod, "__file__", "")).name == MODEL_FILES["nativeModel"]:
        for r in succ["modelRegexRows"]:
            setattr(mod, r["name"], re.compile(W.ecma_to_python(r["ecmaPattern"], flags)))
    setattr(mod, MARK, True)
    return mod


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def load_models(arch, succ, prefix):
    native = Path(arch) / "docs/coop/design-corrections/native"
    mods = {"NE": load(prefix + "ne", native / MODEL_FILES["nativeModel"]), "ST": load(prefix + "st", native / MODEL_FILES["startupModel"]),
            "WI": load(prefix + "wi", native / MODEL_FILES["wireModel"])}
    if succ is not None:
        for m in mods.values():
            install(m, succ)
    return mods


def require_installed(mod):
    if not getattr(mod, MARK, False):
        raise RuntimeError("the owner pattern-evaluation successor is not installed on this owner model instance")

"""Reference host sender consuming the immutable canonical send plan (candidate 04; review-03 RF-4, A-5, A-7).

This is NOT the M3 sender. It states and executes the private plan-consumption contract the M3 sender must honour:

- The Plan-time planner (tools/representability.py) produces an immutable canonical send plan: `schedule` (one slot per
  host-to-worker frame in P3 host order, with sequence, frameType, exact envelope payloadBytes, chunk coordinates
  entry/chunkIndex/byteOffset/byteLength and seal totalChunkCount), `cancelReserve` (one maximal Cancel) and totals.
- The canonical chunk schedule is greedy: every chunk of an entry carries exactly the maximum chunk bytes except the
  entry's last; a zero-length entry has no chunk. It is frame-minimal, NOT byte-minimal, and no other lawful chunking
  is claimed to fit the budget computed for it.
- The sender MUST emit exactly the planned frames in order. A Cancel may take the next sequence number at most once, at
  any point, with payload bytes <= the reserve, and nothing follows it. Any other divergence refuses before the frame is
  written (SENDER_DIVERGENCE:<reason>); running totals are re-checked against the owner limits after every frame.

realize() is an INDEPENDENT realization of the canonical schedule from the request (it shares no code with the planner),
so a plan and its realization agreeing is evidence rather than self-agreement.
"""
import wirecodec as W

Refuse = W.Refuse


def _div(reason, detail=""):
    return Refuse("SENDER_DIVERGENCE:" + reason, detail)


def _envelope(protocol):
    if protocol == "rust-semantic":
        return lambda seq, ft, payload: {"protocolMajor": 3, "direction": "host-to-worker", "sequence": seq, "frameType": ft, "payload": payload}
    return lambda seq, ft, payload: {"protocolMajor": 2, "frameType": ft, "sequence": seq, "payload": payload}


def _nbytes(b):
    return b.n if isinstance(b, W.ByteLen) else len(b)


def _entry_of(frame_type, payload):
    if frame_type == "SnapshotFileChunk":
        return [payload["path"]]
    if frame_type == "DependencySourceChunk":
        return [payload["packageKey"], payload["path"]]
    return [payload["outputOrdinal"]]


def measured(protocol, accounting, frame):
    value = _envelope(protocol)(frame["sequence"], frame["frameType"], frame["payload"]) if accounting["lengthScope"] == "envelope-payload" else frame["payload"]
    return W.encoded_length(value) + (int(accounting["prefixBytes"]) if accounting["prefixIncluded"] else 0)


def consume(plan, protocol, accounting, limits, transcript):
    schedule, reserve = plan["schedule"], plan["cancelReserve"]
    frame_limit = int(limits["maxFramePayloadBytes"])
    totals = protocol in accounting["totalsApplyTo"]
    slot, total, frames, cancelled = 0, 0, 0, False
    for f in transcript:
        if cancelled:
            raise _div("frame-after-cancel", f["frameType"])
        if f["sequence"] != frames:
            raise _div("sequence", "%s!=%s" % (f["sequence"], frames))
        n = measured(protocol, accounting, f)
        if f["frameType"] == "Cancel":
            if reserve is None or n > reserve["payloadBytes"]:
                raise _div("cancel-over-reserve", str(n))
            cancelled = True
        else:
            if slot >= len(schedule):
                raise _div("frame-not-planned", f["frameType"])
            s = schedule[slot]
            if s["frameType"] != f["frameType"]:
                raise _div("frame-type", "%s!=%s" % (f["frameType"], s["frameType"]))
            if "chunkIndex" in s:
                p = f["payload"]
                if (_entry_of(f["frameType"], p), p["chunkIndex"], p["byteOffset"], _nbytes(p["bytes"])) != (s["entry"], s["chunkIndex"], s["byteOffset"], s["byteLength"]):
                    raise _div("chunk-schedule", "slot %d" % slot)
            if "totalChunkCount" in s and f["payload"]["totalChunkCount"] != s["totalChunkCount"]:
                raise _div("seal-count", "slot %d" % slot)
            if n != s["payloadBytes"]:
                raise _div("payload-bytes", "slot %d: %d!=%d" % (slot, n, s["payloadBytes"]))
            slot += 1
        if n > frame_limit:
            raise _div("frame-limit", str(n))
        frames += 1
        total += n
        if totals and (total > int(limits["maxRequestPayloadBytesTotal"]) or frames > int(limits["maxRequestFrames"])):
            raise _div("request-limit", "%d bytes %d frames" % (total, frames))
    return {"framesSent": frames, "payloadBytesSent": total, "slotsConsumed": slot, "cancelled": cancelled,
            "complete": cancelled or slot == len(schedule)}


def realize(req, protocol, limits):
    """The canonical transcript for a request, derived independently of the planner (chunk bytes as ByteLen)."""
    frames = []

    def add(ft, payload):
        frames.append({"frameType": ft, "sequence": len(frames), "payload": payload})

    def custody(manifest_type, chunk_type, seal_type, manifest, id_field, total_field, max_chunk, base_of, length_of):
        add(manifest_type, manifest)
        count = 0
        for e in manifest["entries"]:
            length, offset, index = length_of(e), 0, 0
            while offset < length:
                n = min(max_chunk, length - offset)
                add(chunk_type, dict(base_of(e), chunkIndex=index, byteOffset=offset, bytes=W.ByteLen(n)))
                offset, index, count = offset + n, index + 1, count + 1
        add(seal_type, {id_field: manifest[id_field], "manifestSha256": manifest["manifestSha256"], "entryCount": len(manifest["entries"]),
                        total_field: sum(length_of(e) for e in manifest["entries"]), "totalChunkCount": count})

    add("Hello", req["hello"])
    add("OpenUniverse", req["openUniverse"])
    sm = req["snapshotManifest"]
    custody("SnapshotManifest", "SnapshotFileChunk", "SnapshotSeal", sm, "snapshotId", "totalFileBytes", int(limits["maxSnapshotChunkBytes"]),
            lambda e: {"snapshotId": sm["snapshotId"], "path": e["path"]}, lambda e: e["byteLength"] if e["kind"] == "file" else 0)
    if protocol == "rust-semantic":
        dm = req["dependencyManifest"]
        custody("DependencySourceManifest", "DependencySourceChunk", "DependencySourceSeal", dm, "dependencySourceSetId", "totalBytes",
                int(limits["maxDependencySourceChunkBytes"]),
                lambda e: {"dependencySourceSetId": dm["dependencySourceSetId"], "packageKey": e["packageKey"], "path": e["path"]}, lambda e: e["byteLength"])
        pm = req.get("preparedManifest")
        if pm is not None:
            custody("PreparedOutputManifest", "PreparedOutputChunk", "PreparedOutputSeal", pm, "planId", "totalBlobBytes", int(limits["maxPreparedOutputChunkBytes"]),
                    lambda e: {"planId": pm["planId"], "outputOrdinal": e["outputOrdinal"]}, lambda e: e["blobByteLength"])
    add("Analyze", req["analyze"])
    return frames


def cancel_frame(req, sequence, execution_id=None):
    return {"frameType": "Cancel", "sequence": sequence,
            "payload": {"executionId": execution_id if execution_id is not None else req["openUniverse"]["executionId"],
                        "analysisOrdinal": req["analyze"]["analysisOrdinal"], "reason": "user-interrupt"}}

"""Pre-spawn wire representability admission and the canonical host send plan (candidate 04). Reference scaffolding,
not production admission and not the M3 sender.

Successor selectors (the owner models passed in MUST carry the owner pattern-evaluation successor, tools/owner_successor.py):
  dependency_source_set_admit_successor - phase A (before the owner): a file path of a package the owner will hash that
      fails the owner path schema is a routed refusal (the owner cannot mint its file-manifest identity; before the
      successor it raised an untyped exception). Phase B (after the owner admits; owner DS refusals keep precedence):
      NFC, name/version scalars, key length and canonical-path narrowing.
  prepared_output_set_admit_successor - phase A (before the owner, mode-independent): an ExpansionSiteV1.path or
      GeneratedFileV1.logicalPath failing its owner path schema is a routed refusal. Phase B (owner outcome admitted):
      over-limit rows or blob bytes refuse when prepared mode was selected explicitly and are ignored with a disclosure
      (non-prepared fallback) when it was defaulted - the owner PO-1 mode law.
  plan_rust3_request / plan_ts2_request - the Plan-time planner, producing the immutable canonical send plan.

Byte law (rust2 framing + limitPolicy.aggregateAccounting): every frame is its exact deterministic-CBOR envelope payload;
the 40-byte prefix is excluded; request totals sum envelope payload bytes. Chunk bytes are never materialized. The
canonical schedule is greedy (frame-minimal, NOT byte-minimal); a refusal means "does not fit under the canonical host
send schedule", never "no lawful encoding exists". Codec-level refusal of malicious worker frames is M2 and not claimed.
"""
import unicodedata

import owner_successor as OS
import wirecodec as W

DEP_KEY = "native.dependency-source-not-wire-representable"
PREP_PATH_KEY = "native.prepared-output-not-wire-representable"
PREP_KEY = "native.prepared-output-exceeds-wire-limit"
REQ_KEY = "native.provider-request-exceeds-wire-limit"


def params(doc, rule_id):
    return next(r for r in doc["admission"] if r["id"] == rule_id).get("params", {})


def _nfc(s):
    return unicodedata.normalize("NFC", s) == s


def _fault(kind, subject):
    return {"kind": kind, "subject": subject}


def _refusal(doc, rule_id, faults):
    key = params(doc, rule_id)["route"]["routeKey"]
    return {"key": key, "raw": key + ":" + faults[0]["kind"], "faults": faults}


def owner_schema_ok(NE, pointer, value):
    """Evaluate one value against an owner schema node with the owner validator (successor installed)."""
    try:
        NE.C.validate(dict(NE.SCHEMAS, **{"$ref": pointer}), value)
        return True
    except Exception:  # noqa: BLE001 - jsonschema ValidationError from the owner validator
        return False


# ------------------------------------------------------------------ dependency sources (set admission)
def owner_hashed_rows(NE, lock_text, provided, activated):
    """The provided rows whose files the owner will pass to file_manifest_identity: activated, present in the lock,
    not path-kind (owner _source_kind), provided. Mirrors the owner selection without re-deciding any DS rule."""
    lock = NE.parse_cargo_lock(lock_text)
    by_key = {f'{p["name"]} {p["version"]} {p["source"]}': p for p in lock["packages"]}
    provided_by_key = {f'{r["name"]} {r["version"]} {r["sourceId"]}': r for r in provided}
    out = []
    for key in sorted(activated):
        lock_pkg, row = by_key.get(key), provided_by_key.get(key)
        if lock_pkg is None or row is None:
            continue
        try:
            if NE._source_kind(lock_pkg["source"]) == "path":
                continue
        except NE.AdmissionError:
            continue
        out.append((key, row))
    return out


def dependency_representability_faults(doc, packages, files_by_key):
    kp = params(doc, "DEPSRC-SET-KEY-CONSTRAINTS")
    rep = params(doc, "DEPSRC-WIRE-REPRESENTABILITY")
    lex = doc["privateRepresentation"]["lexicalRules"]
    flags = doc["privateRepresentation"]["patternDialect"]["flags"]
    sep = lex["package-key"]["separator"]
    limit = int(kp["forbidInNameVersionAtOrBelow"])
    faults = []
    for row in packages:
        key = row["name"] + sep + row["version"] + sep + row["sourceId"]
        if any(ord(c) <= limit for c in row["name"] + row["version"]):
            faults.append(_fault(f"name-or-version-scalar-at-or-below-{limit}", key))
        if len(key) > int(kp["maxKeyScalars"]):
            faults.append(_fault(f"package-key-over-{kp['maxKeyScalars']}-scalars", str(len(key))))
        for field in rep["nfcFields"]:
            if not _nfc(row[field]):
                faults.append(_fault(f"non-nfc-{field}", key))
        for path in sorted(files_by_key.get(key, {}), key=lambda p: p.encode("utf-8", "surrogatepass")):
            if not _nfc(path):
                faults.append(_fault("non-nfc-path", path))
            elif len(path) > int(rep["maxPathScalars"]):
                faults.append(_fault(f"path-over-{rep['maxPathScalars']}-scalars", key))
            else:
                try:
                    W.lexical(lex, rep["pathLexical"], path, flags)
                except W.Refuse:
                    faults.append(_fault("path-lexical", path))
    return faults


def dependency_source_set_admit_successor(NE, doc, lock_text, provided, activated):
    OS.require_installed(NE)
    rep = params(doc, "DEPSRC-WIRE-REPRESENTABILITY")
    phase_a = []
    for key, row in owner_hashed_rows(NE, lock_text, provided, activated):
        for path in sorted(row["files"], key=lambda p: p.encode("utf-8", "surrogatepass")):
            if not owner_schema_ok(NE, rep["ownerPathSchema"], path):
                phase_a.append(_fault("path-owner-schema", path))
    if phase_a:
        return {"admitted": False, "identity": None, "refusals": [], "ownerRan": False, "successorRefusal": _refusal(doc, "DEPSRC-WIRE-REPRESENTABILITY", phase_a)}
    out = NE.dependency_source_set_admit(lock_text, provided, activated)
    if not out["admitted"]:
        return dict(out, ownerRan=True, successorRefusal=None)
    files_by_key = {f'{r["name"]} {r["version"]} {r["sourceId"]}': r["files"] for r in provided}
    faults = dependency_representability_faults(doc, out["descriptor"]["packages"], files_by_key)
    if not faults:
        return dict(out, ownerRan=True, successorRefusal=None)
    return dict(out, ownerRan=True, admitted=False, identity=None, successorRefusal=_refusal(doc, "DEPSRC-WIRE-REPRESENTABILITY", faults))


# ------------------------------------------------------------------ prepared outputs (set admission)
def prepared_path_faults(NE, doc, prepared):
    p = params(doc, "PREPARED-V3-PATH-REPRESENTABILITY")
    faults = []
    for i, row in enumerate(prepared.get("rows", [])):
        site, gen = row.get("site"), row.get("generated")
        if isinstance(site, dict) and isinstance(site.get("path"), str) and not owner_schema_ok(NE, p["siteSchema"], site["path"]):
            faults.append(_fault("site-path-owner-schema", "rows[%d]" % i))
        if isinstance(gen, dict) and isinstance(gen.get("logicalPath"), str) and not owner_schema_ok(NE, p["generatedSchema"], gen["logicalPath"]):
            faults.append(_fault("generated-logical-path-owner-schema", "rows[%d]" % i))
    return faults


def prepared_limit_faults(doc, prepared):
    p = params(doc, "PREPARED-V3-WIRE-LIMIT")
    rows = prepared["rows"]
    if p["countScope"] == "all-inert-rows":
        counted = len(rows)
    elif p["countScope"] == "build-script-directives-only":
        counted = sum(1 for r in rows if r["kind"] == "build-script-directives")
    else:
        raise W.Refuse("UNKNOWN_COUNT_SCOPE")
    faults = []
    if counted > int(p["maxEntries"]):
        faults.append(_fault("entries", f"{counted}>{p['maxEntries']}"))
    blob = sum(r["blob"]["byteLength"] for r in rows)
    if blob > int(p["maxTotalBlobBytes"]):
        faults.append(_fault("blob-bytes", f"{blob}>{p['maxTotalBlobBytes']}"))
    return faults


def prepared_output_set_admit_successor(NE, doc, prepared, context, explicit_prepared_mode):
    OS.require_installed(NE)
    phase_a = prepared_path_faults(NE, doc, prepared)
    if phase_a:
        return {"outcome": "rejected", "ownerRan": False, "d9": None, "usableRows": [], "successorRefusal": _refusal(doc, "PREPARED-V3-PATH-REPRESENTABILITY", phase_a)}
    out = NE.prepared_output_set_admit(prepared, context, explicit_prepared_mode)
    if out["outcome"] != "admitted":
        return dict(out, ownerRan=True, successorRefusal=None)
    faults = prepared_limit_faults(doc, prepared)
    if not faults:
        return dict(out, ownerRan=True, successorRefusal=None)
    action = params(doc, "PREPARED-V3-WIRE-LIMIT")["modes"]["explicit" if explicit_prepared_mode else "defaulted"]
    if action == "refuse":
        return dict(out, ownerRan=True, outcome="rejected", successorRefusal=_refusal(doc, "PREPARED-V3-WIRE-LIMIT", faults))
    if action == "fallback-non-prepared-with-disclosure":
        return dict(out, ownerRan=True, outcome="fallback-non-prepared", usableRows=[], successorRefusal=None, preparedOutputSetSelected=False,
                    disclosure="prepared output set exceeds the provider wire limits; ignored, owners analyzed non-prepared", wireLimitDisclosure=faults)
    raise W.Refuse("UNKNOWN_PREPARED_MODE_ACTION", action)


# ------------------------------------------------------------------ Plan-time canonical send plan
def rust3_envelope(seq, frame_type, payload):
    return {"protocolMajor": 3, "direction": "host-to-worker", "sequence": seq, "frameType": frame_type, "payload": payload}


def ts2_envelope(seq, frame_type, payload):
    return {"protocolMajor": 2, "frameType": frame_type, "sequence": seq, "payload": payload}


class Accountant:
    def __init__(self, doc, envelope, frame_limit, total_limit=None, frames_limit=None):
        p = params(doc, "REQUEST-WIRE-ACCOUNTING")
        if p["chunking"] != "greedy-max-chunk":
            raise W.Refuse("UNKNOWN_CHUNKING")
        if p["lengthScope"] not in ("envelope-payload", "inner-payload"):
            raise W.Refuse("UNKNOWN_LENGTH_SCOPE")
        self.p = p
        self.enveloped = p["lengthScope"] == "envelope-payload"
        self.wrap = envelope if self.enveloped else (lambda seq, ft, payload: payload)
        self.prefix = int(p["prefixBytes"]) if p["prefixIncluded"] else 0
        self.frame_limit, self.total_limit, self.frames_limit = frame_limit, total_limit, frames_limit
        self.seq, self.total = 0, 0
        self.frame_faults, self.largest, self.schedule, self.seals = [], {}, [], {}
        self.cancel_reserve = None
        self.memo, self.base_cache = {}, {}

    def frame(self, frame_type, payload, extra=None):
        n = W.encoded_length(self.wrap(self.seq, frame_type, payload), self.memo) + self.prefix
        self._count(frame_type, n, extra)

    def reserve_cancel(self, payload):
        n = W.encoded_length(self.wrap(self.seq, "Cancel", payload)) + self.prefix
        self.cancel_reserve = {"frameType": "Cancel", "payloadBytes": n, "maxCount": 1, "sequence": "the next sequence number at the moment of interrupt"}
        self._count("Cancel", n, None, record=False)

    def chunk_sizes(self, frame_type, base_payload, length, max_chunk, cache_key):
        """Closed-form sizes of the greedy chunk frames of one entry: (size, chunkIndex, byteOffset, byteLength)."""
        if length == 0:
            return []
        bk = (frame_type, cache_key)
        if bk not in self.base_cache:
            probe = self.wrap(0, frame_type, dict(base_payload, chunkIndex=0, byteOffset=0, bytes=W.ByteLen(0)))
            # probe heads: sequence (enveloped only), chunkIndex, byteOffset and the empty byte string are 1 byte each
            self.base_cache[bk] = W.encoded_length(probe) - (4 if self.enveloped else 3)
        base, hl = self.base_cache[bk], W._head_len
        k = -(-length // max_chunk)
        out = []
        for i in range(k):
            n = max_chunk if i < k - 1 else length - (k - 1) * max_chunk
            out.append((base + (hl(self.seq + i) if self.enveloped else 0) + hl(i) + hl(i * max_chunk) + hl(n) + n + self.prefix, i, i * max_chunk, n))
        return out

    def chunks(self, frame_type, base_payload, length, max_chunk, entry):
        for size, i, offset, n in self.chunk_sizes(frame_type, base_payload, length, max_chunk, tuple(entry)):
            self._count(frame_type, size, {"entry": list(entry), "chunkIndex": i, "byteOffset": offset, "byteLength": n})

    def _count(self, frame_type, n, extra, record=True):
        if n > self.largest.get(frame_type, -1):
            self.largest[frame_type] = n
        if n > self.frame_limit and len(self.frame_faults) < 8:
            self.frame_faults.append(_fault("frame:" + frame_type, f"seq{self.seq}:{n}>{self.frame_limit}"))
        if record:
            slot = {"sequence": self.seq, "frameType": frame_type, "payloadBytes": n}
            if extra:
                slot.update(extra)
            self.schedule.append(slot)
        self.total += n
        self.seq += 1

    def result(self, doc):
        faults = list(self.frame_faults)
        if self.total_limit is not None and self.total > self.total_limit:
            faults.append(_fault("request-bytes", f"{self.total}>{self.total_limit}"))
        if self.frames_limit is not None and self.seq > self.frames_limit:
            faults.append(_fault("request-frames", f"{self.seq}>{self.frames_limit}"))
        return {"schedule": self.schedule, "cancelReserve": self.cancel_reserve, "seals": self.seals,
                "frames": self.seq, "payloadBytes": self.total, "largestFrame": self.largest, "faults": faults,
                "refusal": _refusal(doc, "REQUEST-WIRE-ACCOUNTING", faults) if faults else None}


def seal_payload(manifest, id_field, total_field, max_chunk, entry_len):
    entries = manifest["entries"]
    total = sum(entry_len(e) for e in entries)
    chunks = sum(-(-entry_len(e) // max_chunk) for e in entries)
    return {id_field: manifest[id_field], "manifestSha256": manifest["manifestSha256"], "entryCount": len(entries),
            total_field: total, "totalChunkCount": chunks}


def cancel_payload(req):
    return {"executionId": req["openUniverse"]["executionId"], "analysisOrdinal": req["analyze"]["analysisOrdinal"], "reason": "user-interrupt"}


def _totals(doc, protocol, limits):
    if protocol not in params(doc, "REQUEST-WIRE-ACCOUNTING")["totalsApplyTo"]:
        return None, None
    if "maxRequestPayloadBytesTotal" not in limits or "maxRequestFrames" not in limits:
        raise W.Refuse("NO_REQUEST_TOTAL_LIMITS_DECLARED")
    return int(limits["maxRequestPayloadBytesTotal"]), int(limits["maxRequestFrames"])


FILE_LEN = lambda e: e["byteLength"] if e["kind"] == "file" else 0


def _custody(acc, manifest_type, chunk_type, seal_type, manifest, id_field, total_field, max_chunk, base_of, length_of, entry_of):
    acc.frame(manifest_type, manifest)
    for e in manifest["entries"]:
        acc.chunks(chunk_type, base_of(e), length_of(e), max_chunk, entry_of(e))
    seal = seal_payload(manifest, id_field, total_field, max_chunk, length_of)
    acc.seals[seal_type] = seal
    acc.frame(seal_type, seal, {"totalChunkCount": seal["totalChunkCount"]})


def plan_rust3_request(doc, limits, req):
    """Canonical send plan for major 3: P3 host order (P3-01..P3-22) plus one reserved maximal Cancel (P3-29)."""
    total_limit, frames_limit = _totals(doc, "rust-semantic", limits)
    acc = Accountant(doc, rust3_envelope, int(limits["maxFramePayloadBytes"]), total_limit, frames_limit)
    acc.frame("Hello", req["hello"])
    acc.frame("OpenUniverse", req["openUniverse"])
    sm = req["snapshotManifest"]
    _custody(acc, "SnapshotManifest", "SnapshotFileChunk", "SnapshotSeal", sm, "snapshotId", "totalFileBytes", int(limits["maxSnapshotChunkBytes"]),
             lambda e: {"snapshotId": sm["snapshotId"], "path": e["path"]}, FILE_LEN, lambda e: [e["path"]])
    dm = req["dependencyManifest"]
    _custody(acc, "DependencySourceManifest", "DependencySourceChunk", "DependencySourceSeal", dm, "dependencySourceSetId", "totalBytes",
             int(limits["maxDependencySourceChunkBytes"]),
             lambda e: {"dependencySourceSetId": dm["dependencySourceSetId"], "packageKey": e["packageKey"], "path": e["path"]},
             lambda e: e["byteLength"], lambda e: [e["packageKey"], e["path"]])
    pm = req.get("preparedManifest")
    if pm is not None:
        _custody(acc, "PreparedOutputManifest", "PreparedOutputChunk", "PreparedOutputSeal", pm, "planId", "totalBlobBytes", int(limits["maxPreparedOutputChunkBytes"]),
                 lambda e: {"planId": pm["planId"], "outputOrdinal": e["outputOrdinal"]}, lambda e: e["blobByteLength"], lambda e: [e["outputOrdinal"]])
    acc.frame("Analyze", req["analyze"])
    if acc.p["reserveCancel"]:
        acc.reserve_cancel(cancel_payload(req))
    return acc.result(doc)


def plan_ts2_request(doc, limits, req):
    """Canonical send plan for major 2 (no request totals declared; the frame bound applies to every planned frame)."""
    total_limit, frames_limit = _totals(doc, "typescript-semantic", limits)
    acc = Accountant(doc, ts2_envelope, int(limits["maxFramePayloadBytes"]), total_limit, frames_limit)
    acc.frame("Hello", req["hello"])
    acc.frame("OpenUniverse", req["openUniverse"])
    sm = req["snapshotManifest"]
    _custody(acc, "SnapshotManifest", "SnapshotFileChunk", "SnapshotSeal", sm, "snapshotId", "totalFileBytes", int(limits["maxSnapshotChunkBytes"]),
             lambda e: {"snapshotId": sm["snapshotId"], "path": e["path"]}, FILE_LEN, lambda e: [e["path"]])
    acc.frame("Analyze", req["analyze"])
    if acc.p["reserveCancel"]:
        acc.reserve_cancel(cancel_payload(req))
    return acc.result(doc)


def build_plan(plan, fx, prepared_entries_fn):
    """Build a planner request from a compact vector description: groups of n identical-length entries share one entry
    object, so hundreds of thousands of entries and gigabytes of chunk bytes are accounted without materialization.
    Hello/OpenUniverse are owner fixtures; the Analyze payload is an explicit minimal stub whose bytes count like any frame."""
    rust = plan["protocol"] == "rust-semantic"
    prepared = plan.get("prepared")
    if rust:
        hello, ou = fx["wireRustHello"], fx["startupRustOpenUniversePrepared" if prepared else "startupRustOpenUniverse"]
    else:
        hello, ou = fx["wireTsHello"], fx["startupTsOpenUniverse"]
    snap = []
    for g in plan["snapshot"]:
        e = {"path": "s" * g["pathScalars"], "kind": "file", "byteLength": g["byteLength"], "contentSha256": "1" * 64}
        e.update({"executable": False, "targetBytes": None} if rust else {"linkTarget": None})
        snap.extend([e] * g["n"])
    req = {"hello": hello, "openUniverse": ou, "snapshotManifest": {"snapshotId": ou["snapshotId"], "manifestSha256": "0" * 64, "entries": snap}}
    if rust:
        dep = []
        for g in plan["dependency"]:
            e = {"packageKey": g["packageKey"], "path": "d" * g["pathScalars"], "byteLength": g["byteLength"], "contentSha256": "1" * 64}
            dep.extend([e] * g["n"])
        req["dependencyManifest"] = {"dependencySourceSetId": ou["repositoryResolution"]["dependencySourceSetId"], "manifestSha256": "0" * 64, "entries": dep}
        req["preparedManifest"] = None
        if prepared:
            base = fx["prepInert"]["rows"][0]
            config = ["c%0255d" % i for i in range(prepared["configurationCount"])]
            rows = [dict(base, site=dict(base["site"], startByte=i, endByte=i + 1), configuration=config,
                         blob=dict(base["blob"], byteLength=prepared["blobByteLength"])) for i in range(prepared["n"])]
            req["preparedManifest"] = {"planId": ou["planId"], "manifestSha256": "0" * 64, "entries": prepared_entries_fn(rows)}
        req["analyze"] = {"analysisOrdinal": 0, "executionId": ou["executionId"], "snapshotId": ou["snapshotId"], "planId": ou["planId"], "stages": []}
    else:
        req["analyze"] = {"analysisOrdinal": 0, "executionId": ou["executionId"], "snapshotId": ou["snapshotId"], "planId": ou["planId"], "stageRequests": []}
    return req


def plan(doc, limits, plan_desc, fx, prepared_entries_fn):
    req = build_plan(plan_desc, fx, prepared_entries_fn)
    fn = plan_rust3_request if plan_desc["protocol"] == "rust-semantic" else plan_ts2_request
    return fn(doc, limits, req)


def rust3_frames_upper_bound(limits, minimal_dep_entry_len, minimal_snapshot_entry_len, manifest_overhead):
    """Upper bound on canonical-schedule host-to-worker frames for any input the other admissions accept."""
    frame = int(limits["maxFramePayloadBytes"])
    dep_entries = min(int(limits["maxDependencySourceEntries"]), (frame - manifest_overhead) // minimal_dep_entry_len)
    snap_entries = min(int(limits["maxSnapshotEntries"]), (frame - manifest_overhead) // minimal_snapshot_entry_len)
    snap_chunks = snap_entries + int(limits["maxSnapshotTotalFileBytes"]) // int(limits["maxSnapshotChunkBytes"])
    dep_chunks = dep_entries + int(limits["maxDependencySourceTotalBytes"]) // int(limits["maxDependencySourceChunkBytes"])
    prep_chunks = int(limits["maxPreparedOutputEntries"]) + int(limits["maxPreparedOutputTotalBlobBytes"]) // int(limits["maxPreparedOutputChunkBytes"])
    fixed = 10  # Hello, OpenUniverse, 3 manifests, 3 seals, Analyze, reserved Cancel
    return {"bound": fixed + snap_chunks + dep_chunks + prep_chunks, "dependencyEntries": dep_entries, "snapshotEntries": snap_entries,
            "snapshotChunks": snap_chunks, "dependencyChunks": dep_chunks, "preparedChunks": prep_chunks, "fixedFrames": fixed}

"""Owner-joined public route checks (candidate 04; review-02 RF-1, review-03 RF-3, A-1, A-2, A-3, A-9).

Every public field is DERIVED, never compared literal-to-literal: the published rows of public-route-successor.v1.json are
applied in memory to the pinned owner model; termination, envelope errors and exit come from the owner
public_termination_for, failure_envelope_errors and CLASS_TO_EXIT, validated against the pinned common StepTermination
and DomainDetail schemas. Route SEMANTICS are bound by execution:
  route-remedy-keying      every (key, fault kind) the admission vectors produce derives an envelope remedy that states
                           that fault's condition and not the other condition class (remedyKeyingConstraint executed);
  route-join-owner-family  each key's condition class selects its owner family (errorCode, D9_MAP row, route-table row);
  route-origin-closed      the new origin's actor derives the expected class under the owner originatingBoundaryLaw;
  route-timing-anchored    timing follows the wrapped owner function and its pinned owner text, plus executed behaviour;
  route-prepared-modes     the prepared mode actions follow the owner PO-1 mode law and execute in both modes;
  route-selectors-owner-source  owner function and callee-closure source digests (A-9).
"""
import copy
import inspect
import json

from jsonschema import Draft202012Validator
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

import owner_successor as OS
import public_routes as PR
import representability as REP

TIMING_PHRASES = {"before-plan-id": "before PlanId", "before-plan-construction": "before Plan construction", "plan-time-no-spawn": "Plan time (no spawn)"}
OWNER_FUNCTION_TIMING = {"dependency_source_set_admit": "before-plan-id", "prepared_output_set_admit": "before-plan-construction", None: "plan-time-no-spawn"}
ACTOR_LAW = {"external-input": ("Invalid external input is an admission rejection", "request-rejected"),
             "host-generated-internal-layer": ("an invalid host-generated internal layer is a host invariant fault", "operational-failed")}
REPRESENTABILITY_MARK, BOUND_MARK = "cannot be carried", "limits"


def remedy_requirements(kind):
    """(phrases the remedy must contain, phrase it must not contain) for one fault kind; the checker's own reading of the
    fault's condition, independent of the published successor."""
    if kind.startswith("non-nfc"):
        return ["non-NFC", REPRESENTABILITY_MARK], BOUND_MARK
    if kind.startswith("name-or-version-scalar-at-or-below"):
        return ["U+0020", REPRESENTABILITY_MARK], BOUND_MARK
    if kind.startswith("package-key-over"):
        return ["package key", REPRESENTABILITY_MARK], BOUND_MARK
    if "path" in kind:
        return ["path", "'..'", REPRESENTABILITY_MARK], BOUND_MARK
    if kind in ("entries", "blob-bytes"):
        return ["prepared outputs", BOUND_MARK], REPRESENTABILITY_MARK
    if kind.startswith("frame:"):
        return ["frame", BOUND_MARK], REPRESENTABILITY_MARK
    if kind in ("request-bytes", "request-frames"):
        return ["request limits"], REPRESENTABILITY_MARK
    return None, None


class Routes:
    def __init__(self, ref):
        self.r, self.s, self.NE, self.NE_S = ref, ref.s, ref.NE, ref.NE_S
        self.doc = json.loads((self.s.out / "public-route-successor.v1.json").read_text())
        self.common = json.loads(self.s.raw["workflowCommon"])
        self.registry_doc = json.loads(self.s.raw["publicDetailRegistry"])

    def add(self, *a):
        self.r.add(*a)

    def validator(self, defname):
        schema = PR.common_schema_with_members(self.common, self.doc)
        cid = schema["$id"]
        reg = Registry().with_resource(cid, Resource(contents=schema, specification=DRAFT202012))
        return Draft202012Validator({"$ref": cid + "#/$defs/" + defname}, registry=reg)

    def family(self, key):
        return self.doc["conditionClasses"][self.doc["addKeys"][key]["conditionClass"]]["ownerFamily"]

    # ------------------------------------------------------------------
    def rule_references(self):
        keys = self.doc["addKeys"]
        refs, bad = {}, []
        for rule in self.s.wire["admission"]:
            p = rule.get("params", {})
            if "refusal" in p:
                bad.append(rule["id"] + ": literal refusal")
            rt = p.get("route")
            if rt is None:
                continue
            if rt["routeKey"] not in keys or rt["successor"] != "public-route-successor.v1.json#/addKeys/" + rt["routeKey"]:
                bad.append(rule["id"] + ": " + rt["routeKey"])
            refs.setdefault(rt["routeKey"], []).append(rule["id"])
        selectors = {k: sorted(self.doc["selectors"].get(k, {}).get("rules", [])) for k in keys}
        refs_sorted = {k: sorted(v) for k, v in refs.items()}
        self.add("route-rule-references", not bad and set(refs) == set(keys) and all(set(refs_sorted.get(k, [])) <= set(selectors[k]) and refs_sorted.get(k) for k in keys),
                 {"bad": bad, "references": refs_sorted})

    def join(self):
        NE = self.NE
        st_v, dd_v = self.validator("StepTermination"), self.validator("DomainDetail")
        codes = {m["code"]: m["remedy"] for m in self.doc["addDomainDetailCodes"]}
        with PR.Overlay(NE, self.doc) as ov:
            for key, row in self.doc["addKeys"].items():
                try:
                    fam = self.family(key)["routeRegistry"]
                    owner = NE.PUBLIC_ROUTE_REGISTRY["keys"][fam["key"]]
                    owner_route = owner["byOriginatingBoundary"][fam["origin"]] if owner["originDependent"] else owner["route"]
                    d = ov.derive(key + ":probe-subject")
                    term, errors = d["termination"], d["errors"]
                    schema_errors = [e.message for e in st_v.iter_errors(term)] + [e.message for err in errors for e in dd_v.iter_errors(err)]
                    ok = (not schema_errors and self.doc["publicForm"] == "internal-key-domainDetail-absent"
                          and set(term) == {"class", "errorCode"} and term["class"] == owner_route["class"] and term["errorCode"] == owner_route["errorCode"]
                          and d["exitCode"] == NE.CLASS_TO_EXIT[owner_route["class"]]
                          and len(errors) == 1 and errors[0]["code"] in codes and errors[0]["remedy"] == codes[errors[0]["code"]]
                          and errors[0]["subject"] == key + ":probe-subject")
                    detail = {"termination": term, "exitCode": d["exitCode"], "envelope": errors[0]["code"] if errors else None, "schemaErrors": schema_errors[:3],
                              "ownerFamilyRoute": {"key": fam["key"], "class": owner_route["class"], "errorCode": owner_route["errorCode"]}}
                except Exception as exc:  # noqa: BLE001
                    ok, detail = False, type(exc).__name__ + ": " + str(exc)[:240]
                self.add("route-join:" + key, ok, detail)

    def owner_family(self):
        NE, fx = self.NE, self.r.fx
        executed = NE.prepared_output_set_admit(copy.deepcopy(fx["prepDylib"]), fx["ctx"], True)["d9"]
        results = {}
        with PR.Overlay(NE, self.doc) as ov:
            for row in self.doc["routeTableRows"]:
                fam = self.family(row["routeKey"])
                d9 = NE.D9_MAP[fam["modelD9Map"]]
                d = ov.derive(row["routeKey"])
                target = fam["routeTable"]
                line = self.s.lines(target["pin"])[target["line"] - 1]
                ok = (row["target"] == target and row["class"] == d["termination"]["class"] == d9["class"]
                      and row["errorCode"] == d["termination"]["errorCode"] == d9["code"] and int(row["exitCode"]) == d["exitCode"] == d9["exitCode"]
                      and target["rowNeedle"] in line and "`%s`" % d9["code"] in line and "`request-rejected` (2)" in line
                      and row["routeKey"] in row["carrier"] and self.doc["addKeys"][row["routeKey"]]["route"]["envelopeDetail"] in row["carrier"])
                if self.doc["addKeys"][row["routeKey"]]["conditionClass"] == "representability":
                    ok = ok and executed["code"] == d9["code"] and executed["exitCode"] == d9["exitCode"]
                results[row["routeKey"]] = ok
        self.add("route-join-owner-family", bool(results) and all(results.values()) and set(results) == set(self.doc["addKeys"]),
                 {"rows": results, "executedOwnerRepresentabilityRefusal": executed})

    def remedy_keying(self):
        codes = {m["code"]: m["remedy"] for m in self.doc["addDomainDetailCodes"]}
        pairs = set()
        for vecs in self.s.vectors["vectors"].values():
            for vec in vecs:
                exp = vec.get("expect") or ""
                if vec["kind"] == "refuse" and exp.startswith("ROUTE:"):
                    _, key, kind = exp.split(":", 2)
                    pairs.add((key, kind))
        bad, checked = [], 0
        with PR.Overlay(self.NE, self.doc) as ov:
            for key, kind in sorted(pairs):
                need, forbid = remedy_requirements(kind)
                if need is None or key not in self.doc["addKeys"]:
                    bad.append([key, kind, "unclassified"])
                    continue
                try:
                    remedy = ov.derive(key + ":" + kind)["errors"][0]["remedy"]
                except Exception as exc:  # noqa: BLE001
                    bad.append([key, kind, type(exc).__name__])
                    continue
                checked += 1
                if any(p not in remedy for p in need) or forbid in remedy:
                    bad.append([key, kind, "remedy does not state this condition"])
        keys_with_faults = {k for k, _ in pairs}
        self.add("route-remedy-keying", not bad and checked >= 10 and keys_with_faults == set(self.doc["addKeys"]) and len(codes) == 2,
                 {"pairsChecked": checked, "bad": bad[:6]})

    def origins(self):
        NE = self.NE
        existing = sorted({o for r in NE.PUBLIC_ROUTE_REGISTRY["keys"].values() for o in r.get("possibleOrigins", [])})
        try:
            NE.public_termination_for(next(iter(self.doc["addKeys"])), self.doc["newOrigin"]["id"])
            unregistered_refused = False
        except NE.AdmissionError:
            unregistered_refused = True
        law = NE.PUBLIC_ROUTE_REGISTRY["originatingBoundaryLaw"]
        actor = self.doc["newOrigin"].get("actor")
        phrase, expected_class = ACTOR_LAW.get(actor, (None, None))
        per_key = {}
        with PR.Overlay(NE, self.doc) as ov:
            for key, row in self.doc["addKeys"].items():
                refused = []
                for origin in existing:
                    try:
                        NE.public_termination_for(key, origin)
                        refused.append(False)
                    except NE.AdmissionError:
                        refused.append(True)
                derived_class = ov.derive(key)["termination"]["class"]
                per_key[key] = all(refused) and row["possibleOrigins"] == [self.doc["newOrigin"]["id"]] and row["originDependent"] is False and derived_class == expected_class
        self.add("route-origin-closed", unregistered_refused and phrase is not None and phrase in law and all(per_key.values()) and self.doc["newOrigin"]["id"] not in existing,
                 {"existingOrigins": existing, "actor": actor, "lawClass": expected_class, "perKey": per_key, "withoutSuccessorRefused": unregistered_refused})

    def remedies(self):
        NE = self.NE
        codes = [r["code"] for r in self.registry_doc["records"]]
        enum = self.common["$defs"]["DomainDetailCode"]["enum"]
        new = [m["code"] for m in self.doc["addDomainDetailCodes"]]
        used = {row["route"]["envelopeDetail"] for row in self.doc["addKeys"].values()}
        aliases = json.dumps(self.registry_doc.get("internalAliases", {}))
        ok = (sorted(codes) == sorted(enum) and not set(new) & set(codes) and not set(new) & set(NE.PUBLIC_ROUTE_REMEDIES)
              and set(new) == used and len(new) == len(set(new))
              and all(m["remedy"] not in set(NE.PUBLIC_ROUTE_REMEDIES.values()) for m in self.doc["addDomainDetailCodes"])
              and not any(k in aliases for k in list(self.doc["addKeys"]) + new))
        self.add("route-remedy-not-reused", ok, {"registryRecords": len(codes), "commonEnum": len(enum), "added": new, "usedAsEnvelopeDetail": sorted(used)})

    def timing(self):
        NE_S, fx, doc = self.NE_S, self.r.fx, self.s.wire
        for key, sel in self.doc["selectors"].items():
            try:
                a = sel["timingAnchor"]
                line = self.s.lines(a["pin"])[a["line"] - 1]
                phrase = TIMING_PHRASES.get(sel["timing"])
                fn = sel["ownerFunction"].split("#")[1] if sel["ownerFunction"] else None
                ok = (sel["timing"] in self.doc["preSpawnTimings"] and phrase is not None and a["needle"] in line and phrase in a["needle"]
                      and OWNER_FUNCTION_TIMING.get(fn) == sel["timing"])
                behaviour = None
                if key == PR.DEP_KEY:
                    lock, provided, activated = self.r.depsrc_case({"files": ["Cargo.toml", "C:x"]})
                    out = REP.dependency_source_set_admit_successor(NE_S, doc, lock, provided, activated)
                    behaviour = {"admitted": out["admitted"], "dependencySourceSetIdMinted": out["identity"] is not None}
                    ok = ok and out["admitted"] is False and out["identity"] is None and out["successorRefusal"]["key"] == key
                elif key == PR.PREP_PATH_KEY:
                    prep, explicit = self.r.prepared_path_case({"generatedLogicalPath": "x" + chr(10) + "/../y.rs"})
                    out = REP.prepared_output_set_admit_successor(NE_S, doc, prep, fx["ctx"], explicit)
                    behaviour = {"outcome": out["outcome"], "ownerRan": out["ownerRan"]}
                    ok = ok and out["outcome"] == "rejected" and out["successorRefusal"]["key"] == key
                elif key == PR.PREP_KEY:
                    prep, explicit = self.r.prepared_case({"fixture": "prepInert", "rows": 257})
                    out = REP.prepared_output_set_admit_successor(NE_S, doc, prep, fx["ctx"], explicit)
                    behaviour = {"outcome": out["outcome"]}
                    ok = ok and out["outcome"] == "rejected" and out["successorRefusal"]["key"] == key
                else:
                    fate = sel.get("planIdFate", "")
                    with PR.Overlay(self.NE, self.doc) as ov:
                        term = ov.derive(key)["termination"]
                    behaviour = {"terminationMembers": sorted(term), "planIdFate": bool(fate)}
                    ok = ok and all(w in fate for w in ("plan2", "run3", "Coverage", "no worker")) and not ({"runId", "coverageId", "executionId"} & set(term)) \
                        and "timing only" in sel.get("anchorScope", "")
                detail = {"timing": sel["timing"], "line": line.strip()[:120], "behaviour": behaviour}
            except Exception as exc:  # noqa: BLE001
                ok, detail = False, type(exc).__name__ + ": " + str(exc)[:240]
            self.add("route-timing-anchored:" + key, ok, detail)

    def selectors(self):
        text = self.s.raw["nativeModel"].decode("utf-8")
        bad = []
        for key, sel in self.doc["selectors"].items():
            if sel["ownerFunction"] is None:
                continue
            name = sel["ownerFunction"].split("#")[1]
            closure = OS.source_closure(text, [name])
            if closure.get(name) != sel.get("ownerFunctionSourceSha256"):
                bad.append(key + ": owner source digest")
            if closure != sel.get("calleeClosureSha256"):
                bad.append(key + ": callee closure digests")
            wrapper = getattr(REP, sel["successorFunction"].split("#")[1])
            if "NE." + name + "(" not in inspect.getsource(wrapper):
                bad.append(key + ": wrapper does not call the owner")
        self.add("route-selectors-owner-source", not bad, bad)

    def prepared_modes(self):
        NE_S, fx, doc = self.NE_S, self.r.fx, self.s.wire
        md = " ".join(x.strip() for x in self.s.lines("nativeMd")[1849:1858])
        derived = {}
        if "refused before Plan construction" in md and "when prepared mode was selected explicitly" in md:
            derived["explicit"] = "refuse"
        if "non-prepared fallback when prepared mode was defaulted" in md:
            derived["defaulted"] = "fallback-non-prepared-with-disclosure"
        params = next(r for r in doc["admission"] if r["id"] == "PREPARED-V3-WIRE-LIMIT")["params"]["modes"]
        sel = self.doc["selectors"][PR.PREP_KEY]
        row = next(r for r in self.doc["routeTableRows"] if r["routeKey"] == PR.PREP_KEY)
        runs = {}
        for name, case, explicit in (("explicit-257", {"fixture": "prepInert", "rows": 257}, True), ("defaulted-257", {"fixture": "prepInert", "rows": 257}, False),
                                     ("defaulted-256", {"fixture": "prepInert", "rows": 256}, False)):
            prep, _ = self.r.prepared_case(case)
            out = REP.prepared_output_set_admit_successor(NE_S, doc, prep, fx["ctx"], explicit)
            runs[name] = {"outcome": out["outcome"], "refusal": (out.get("successorRefusal") or {}).get("key"),
                          "disclosure": [f["kind"] for f in out.get("wireLimitDisclosure") or []], "usableRows": len(out.get("usableRows", []))}
        executed = (runs["explicit-257"]["outcome"] == "rejected" and runs["explicit-257"]["refusal"] == PR.PREP_KEY
                    and runs["defaulted-257"] == {"outcome": "fallback-non-prepared", "refusal": None, "disclosure": ["entries"], "usableRows": 0}
                    and runs["defaulted-256"]["outcome"] == "admitted")
        ok = (len(derived) == 2 and params == derived and sel.get("modes") == derived and executed
              and "selected explicitly" in row["condition"] and "defaulted" in row["condition"] and "no refusal" in row["condition"])
        self.add("route-prepared-modes", ok, {"ownerDerived": derived, "params": params, "runs": runs})

    def run(self):
        for step in (self.rule_references, self.join, self.owner_family, self.remedy_keying, self.origins, self.remedies, self.timing, self.selectors, self.prepared_modes):
            try:
                step()
            except Exception as exc:  # noqa: BLE001
                self.add("step:routes." + step.__name__, False, type(exc).__name__ + ": " + str(exc)[:300])

